arguments.command:
python3 - <<'EOF'
import json, glob

total = 0
for f in sorted(glob.glob('data/*.jsonl')):
    with open(f) as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            rec = json.loads(line)
            if rec.get('kind') != 'span':
                continue
            el = rec.get('body', {}).get('span', {}).get('elapsed')
            if el is None:
                continue
            v = el['value']; u = el['unit']
            if u == 'ms':
                total += v
            elif u == 'us':
                total += v // 1000
            elif u == 's':
                total += v * 1000
            else:
                raise SystemExit(f'unknown unit {u} in {f}')
print(total)
EOF
